import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import {
  blobRangeSource,
  cachedRangeSource,
  decodeChunk,
  type Hdf5ChunkRef,
  Hdf5Dataset,
  Hdf5File,
  Hdf5Group,
  httpRangeSource,
  type RangeSource,
} from "../src/data/hdf5/index.js";

// Fixtures are generated by h5py (see test/fixtures/hdf5/expected.json for
// shapes, chunk lists and attribute values recorded from h5py).
const FIXTURES = join(__dirname, "fixtures", "hdf5");

interface DatasetExpect {
  shape: number[];
  chunks: number[] | null;
  dtype: string;
  chunkList:
    | Array<[number[], number, number, number]>
    | { count: number; first: unknown[]; last: unknown[] }
    | null;
  formula: string;
}
const expected = JSON.parse(
  readFileSync(join(FIXTURES, "expected.json"), "utf8"),
) as Record<string, { datasets: Record<string, DatasetExpect> }> & {
  attrs: Record<string, Record<string, unknown>>;
};

function openFixture(name: string) {
  const buf = readFileSync(join(FIXTURES, name));
  const src = blobRangeSource(new Blob([buf]));
  return { src, file: Hdf5File.open(src) };
}

/** Expected little-endian bytes from the generator formulas in the fixture script. */
function expectedBytes(ds: DatasetExpect): Uint8Array {
  const n = ds.shape.reduce((a, b) => a * b, 1);
  const kind = ds.dtype.slice(1);
  const size = Number(kind.slice(1));
  const mod = { 1: 251, 2: 65521, 4: 2 ** 31 - 1 }[size] ?? 0;
  const arr =
    kind === "f4"
      ? new Float32Array(n)
      : kind === "u1"
        ? new Uint8Array(n)
        : kind === "u2"
          ? new Uint16Array(n)
          : kind === "i2"
            ? new Int16Array(n)
            : kind === "i4"
              ? new Int32Array(n)
              : null;
  if (!arr) throw new Error(`no expectation for ${ds.dtype}`);
  for (let i = 0; i < n; i++) {
    let v: number;
    if (ds.formula === "float") v = (i % 1000) * 0.25 - 17.5;
    else if (ds.formula === "hash")
      v = ((Math.imul(i, 2654435761 | 0) >>> 0) >>> 13) & 255;
    else v = (i * 37 + Math.floor(i / 7)) % mod;
    if (ds.formula === "int-partial") {
      // Only chunks [0:16,0:16,0:16] and [16:32,16:32,0:16] were written.
      const [, Y, X] = ds.shape as [number, number, number];
      const x = i % X;
      const y = Math.floor(i / X) % Y;
      const z = Math.floor(i / (X * Y));
      const a = z < 16 && y < 16 && x < 16;
      const b = z >= 16 && y >= 16 && x < 16;
      if (!a && !b) v = 0;
    }
    arr[i] = v;
  }
  return new Uint8Array(arr.buffer);
}

const cmpOffset = (a: number[], b: number[]) => {
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return a[i]! - b[i]!;
  return 0;
};
const asTuple = (r: Hdf5ChunkRef) => [
  r.offset,
  r.address,
  r.size,
  r.filterMask,
];

const FILES = ["old.h5", "v108.h5", "latest.h5", "v114.h5", "lz4.h5"];

describe.each(FILES)("HDF5 fixture %s", (name) => {
  const exp = expected[name]!;

  it("matches h5py datasets: shape, dtype, chunk index and values", async () => {
    const { file } = openFixture(name);
    const f = await file;
    for (const [path, ds] of Object.entries(exp.datasets)) {
      const node = await f.get(path);
      expect(node, path).toBeInstanceOf(Hdf5Dataset);
      const d = node as Hdf5Dataset;
      expect(d.shape, path).toEqual(ds.shape);
      expect(d.chunkShape, path).toEqual(ds.chunks);
      const size = Number(ds.dtype.slice(2));
      expect(d.dtype.size, path).toBe(size);
      expect(d.dtype.littleEndian, path).toBe(ds.dtype[0] !== ">");
      const cls =
        ds.dtype[1] === "f" ? "float" : ds.dtype[1] === "i" ? "int" : "uint";
      expect(d.dtype.class, path).toBe(cls);
      if (ds.formula) expect((await d.attrs()).formula, path).toBe(ds.formula);
      if (path === "/extensible") {
        await expect(d.chunks()).rejects.toThrow(/unsupported chunk index/);
        continue;
      }
      if (ds.chunkList) {
        const refs = (await d.chunks())
          .slice()
          .sort((a, b) => cmpOffset(a.offset, b.offset));
        if (Array.isArray(ds.chunkList)) {
          expect(refs.map(asTuple), path).toEqual(ds.chunkList);
        } else {
          expect(refs.length, path).toBe(ds.chunkList.count);
          expect(refs.slice(0, 4).map(asTuple), path).toEqual(
            ds.chunkList.first,
          );
          expect(refs.slice(-4).map(asTuple), path).toEqual(ds.chunkList.last);
        }
      }
      const all = await d.readAll();
      expect(all.length, path).toBe(expectedBytes(ds).length);
      expect(
        Buffer.from(all).equals(Buffer.from(expectedBytes(ds))),
        path,
      ).toBe(true);
    }
  });

  if (name === "lz4.h5" || name === "v114.h5") return;

  it("reads root, Imaris char-array and string attributes", async () => {
    const f = await openFixture(name).file;
    const rootAttrs = await (await f.root()).attrs();
    const want = expected.attrs["/"]!;
    for (const [k, v] of Object.entries(want)) {
      if (k === "Big64") expect(rootAttrs[k]).toBe(BigInt(v as string));
      else expect(rootAttrs[k], k).toEqual(v);
    }
    const ch = (await f.get("/DataSetInfo/Channel 0")) as Hdf5Group;
    expect(await ch.attrs()).toEqual(expected.attrs["/DataSetInfo/Channel 0"]);
    const lvl = (await f.get(
      "/DataSet/ResolutionLevel 0/TimePoint 0/Channel 0",
    )) as Hdf5Group;
    const la = await lvl.attrs();
    expect(la.ImageSizeX).toBe("17");
    expect(la.ImageSizeY).toBe("33");
    expect(la.ImageSizeZ).toBe("20");
  });

  it("lists groups (compact, dense and symbol-table links)", async () => {
    const f = await openFixture(name).file;
    const root = await f.root();
    const keys = await root.keys();
    expect(keys).toContain("DataSet");
    expect(keys).toContain("DataSetInfo");
    expect(keys).toContain("Many");
    const many = (await f.get("/Many")) as Hdf5Group;
    expect(await many.keys()).toEqual(
      Array.from({ length: 12 }, (_, k) => `Child ${k}`).sort(),
    );
    expect(await many.get("Child 7")).toBeInstanceOf(Hdf5Group);
    expect(await many.get("missing")).toBeNull();
    expect(await f.get("/Many/Child 11")).toBeInstanceOf(Hdf5Group);
    expect(await f.get("/nope/x")).toBeNull();
    // 300 links: multi-block fractal heap / multi-level B-trees
    const lots = (await f.get("/Lots")) as Hdf5Group;
    const names = Array.from(
      { length: 300 },
      (_, k) =>
        `hard link number ${String(k).padStart(4, "0")} with a fairly long name`,
    );
    expect(await lots.keys()).toEqual(names);
    const linked = await lots.get(names[299]!);
    expect(await (linked as Hdf5Group).keys()).toEqual(await many.keys());
    if (name !== "old.h5") {
      // > 8 attributes → dense attribute storage
      const attrs = await many.attrs();
      expect(Object.keys(attrs).sort()).toEqual(
        Array.from(
          { length: 12 },
          (_, k) => `Attr${String(k).padStart(2, "0")}`,
        ),
      );
      expect(attrs.Attr05).toBe("55");
    }
  });
});

describe("HDF5 chunk access", () => {
  it("readChunk decodes single chunks and uses the raw (uncached) source", async () => {
    const { src, file } = openFixture("v108.h5");
    const f = await file;
    const d = (await f.get(
      "/DataSet/ResolutionLevel 0/TimePoint 0/Channel 0/Data",
    )) as Hdf5Dataset;
    expect(d.filters.map((x) => x.id)).toEqual([1]);
    expect(d.filters[0]!.name).toBe("deflate");
    const refs = await d.chunks();
    const metaBytes = f.meta.stats.bytes;
    const before = src.stats.requests;
    const first = refs.find((r) => r.offset.every((o) => o === 0))!;
    const data = await d.readChunk(first);
    expect(data.length).toBe(8 * 16 * 8);
    expect(src.stats.requests).toBe(before + 1);
    expect(f.meta.stats.bytes).toBe(metaBytes); // bulk data bypasses the page cache
    // element (z=1, y=2, x=3) of the first chunk = global index 1*33*17 + 2*17 + 3
    const i = 1 * 33 * 17 + 2 * 17 + 3;
    expect(data[1 * 16 * 8 + 2 * 8 + 3]).toBe(
      (i * 37 + Math.floor(i / 7)) % 251,
    );
  });

  it("decodeChunk handles shuffle, fletcher32 and filterMask", async () => {
    const f = await openFixture("v108.h5").file;
    const d = (await f.get("/f32_gzip_shuffle_fletcher")) as Hdf5Dataset;
    expect(d.filters.map((x) => x.id)).toEqual([2, 1, 3]);
    const ref = (await d.chunks())[0]!;
    const src = blobRangeSource(
      new Blob([readFileSync(join(FIXTURES, "v108.h5"))]),
    );
    const stored = await src.read(ref.address, ref.size);
    const out = await decodeChunk(stored, d.filters, ref.filterMask, 4);
    expect(out).toEqual(await d.readChunk(ref));
    // All filters masked → bytes pass through untouched.
    expect(await decodeChunk(stored, d.filters, 0b111, 4)).toBe(stored);
  });

  it("LZ4 plugin framing: raw blocks and overlapping matches", async () => {
    const lz4 = [{ id: 32004, name: "lz4", clientData: [], optional: false }];
    const enc = (s: string) => [...s].map((ch) => ch.charCodeAt(0));
    // biome-ignore format: byte layout
    const frame = new Uint8Array([
      0, 0, 0, 0, 0, 0, 0, 21, // original size (BE u64)
      0, 0, 0, 17, // block size
      0, 0, 0, 12, // block 1: 12 compressed bytes
      0x35, ...enc("abc"), 3, 0, // 3 literals, match offset 3 len 5+4 (overlapping)
      0x50, ...enc("xyzxy"), // 5 trailing literals
      0, 0, 0, 4, ...enc("1234"), // block 2 (4 bytes): stored raw (size == block size)
    ]);
    const out = await decodeChunk(frame, lz4, 0, 1);
    expect(String.fromCharCode(...out)).toBe("abcabcabcabcxyzxy1234");
  });

  it("rejects unsupported filters clearly", async () => {
    await expect(
      decodeChunk(
        new Uint8Array(4),
        [{ id: 32008, name: "", clientData: [], optional: false }],
        0,
        1,
      ),
    ).rejects.toThrow(/unsupported filter 32008/);
  });
});

describe("range sources", () => {
  function fakeSource(size: number) {
    const data = new Uint8Array(size).map((_, i) => i & 255);
    const calls: Array<[number, number]> = [];
    const src: RangeSource = {
      stats: { bytes: 0, requests: 0 },
      async read(offset, length) {
        calls.push([offset, length]);
        await new Promise((r) => setTimeout(r, 1));
        return data.subarray(offset, Math.min(size, offset + length));
      },
    };
    return { data, calls, src };
  }

  it("cachedRangeSource coalesces, de-dups and handles EOF", async () => {
    const { data, calls, src } = fakeSource(10_000);
    const c = cachedRangeSource(src, { pageSize: 1024, maxGapPages: 0 });
    const [a, b, d] = await Promise.all([
      c.read(100, 50),
      c.read(1000, 100), // spans pages 0-1
      c.read(1500, 10), // page 1 again (in-flight de-dup)
    ]);
    expect(calls).toEqual([[0, 2048]]);
    expect([...a]).toEqual([...data.subarray(100, 150)]);
    expect([...b]).toEqual([...data.subarray(1000, 1100)]);
    expect([...d]).toEqual([...data.subarray(1500, 1510)]);
    // Separate runs → separate requests; cached pages are not refetched.
    await Promise.all([c.read(0, 10), c.read(5000, 10), c.read(8000, 10)]);
    expect(calls.length).toBe(3);
    // EOF: short read
    const tail = await c.read(9990, 100);
    expect(tail.length).toBe(10);
    expect(c.stats.requests).toBe(calls.length);
  });

  it("cachedRangeSource evicts LRU pages", async () => {
    const { calls, src } = fakeSource(10_000);
    const c = cachedRangeSource(src, { pageSize: 1024, maxPages: 2 });
    await c.read(0, 1);
    await c.read(2048, 1);
    await c.read(0, 1); // hit, refresh
    await c.read(4096, 1); // evicts page 2
    await c.read(0, 1); // still cached
    expect(calls.length).toBe(3);
    await c.read(2048, 1);
    expect(calls.length).toBe(4);
  });

  it("httpRangeSource sends GET with Range (never HEAD) and requires 206", async () => {
    const seen: RequestInit[] = [];
    const mk = (status: number) =>
      (async (_url: string | URL | Request, init?: RequestInit) => {
        seen.push(init ?? {});
        return new Response(new Uint8Array([1, 2, 3]), { status });
      }) as typeof fetch;
    const ok = httpRangeSource("https://example.test/x.ims", {
      fetch: mk(206),
    });
    const got = await ok.read(10, 3);
    expect([...got]).toEqual([1, 2, 3]);
    expect(seen[0]!.method ?? "GET").toBe("GET");
    expect((seen[0]!.headers as Record<string, string>).Range).toBe(
      "bytes=10-12",
    );
    expect(ok.stats).toEqual({ bytes: 3, requests: 1 });
    const bad = httpRangeSource("https://example.test/x.ims", {
      fetch: mk(200),
    });
    await expect(bad.read(0, 3)).rejects.toThrow(/Range/);
  });
});

// Optional: the real 2.6 GB Imaris file on S3 (HDF5_NETWORK_TEST=1).
const IMS_URL =
  "https://lsp-public-data.s3.amazonaws.com/yapp-2023-3d-melanoma/LSP22408.ims";
describe.skipIf(!process.env.HDF5_NETWORK_TEST)("remote Imaris file", () => {
  it("indexes level 0 channel 0 like h5py", { timeout: 60_000 }, async () => {
    const src = httpRangeSource(IMS_URL);
    const f = await Hdf5File.open(src);
    const d = (await f.get(
      "/DataSet/ResolutionLevel 0/TimePoint 0/Channel 0/Data",
    )) as Hdf5Dataset;
    expect(d.shape).toEqual([112, 1024, 1024]);
    expect(d.chunkShape).toEqual([16, 128, 128]);
    const refs = await d.chunks();
    expect(refs.length).toBe(448);
    expect(refs[0]).toEqual({
      offset: [0, 0, 0],
      address: 313163,
      size: 4596,
      filterMask: 0,
    });
    const chunk = await d.readChunk(refs[0]!);
    expect(chunk.length).toBe(16 * 128 * 128 * 4);
    const ch = (await f.get("/DataSetInfo/Channel 0")) as Hdf5Group;
    expect((await ch.attrs()).Name).toBe("hoechst");
  });
});
